questions.text:
¿Qué se muestra en consola?

let edad = 20;
let tieneCedula = true;

if (edad >= 18 && tieneCedula) {
    console.log("Puede ingresar");
} else {
    console.log("No puede ingresar");
}

¿Cuál será la salida del siguiente código?

let dia = "domingo";

if (dia === "sábado" || dia === "domingo") {
    console.log("Fin de semana");
} else {
    console.log("Día laboral");
}

¿Qué se muestra en consola?

let nota = 8;
let asistencia = 70;

if (nota >= 7 && asistencia >= 80) {
    console.log("Aprueba");
} else if (nota >= 7 || asistencia >= 80) {
    console.log("Revisión");
} else {
    console.log("Reprueba");
}

¿Qué imprime el siguiente código?

let bloqueado = false;

if (!bloqueado) {
    console.log("Acceso permitido");
} else {
    console.log("Acceso bloqueado");
}

¿Cuál es la salida del siguiente código?

let nota = 6;
let proyecto = true;

if (nota >= 9) {
    console.log("Excelente");
} else if (nota >= 7) {
    console.log("Aprobado");
} else if (nota >= 5 && proyecto) {
    console.log("Recuperación");
} else {
    console.log("Reprobado");
}

¿Por qué la siguiente condición nunca será verdadera?

let edad = 20;

if (edad > 18 && edad < 18) {
    console.log("Condición cumplida");
}

¿Cuál es el valor final de total?

let total = 0;

for (let i = 1; i <= 4; i++) {
    total = total + i;
}

console.log(total);

¿Cuál será la salida del ciclo?

for (let i = 10; i >= 2; i -= 2) {
    console.log(i);
}

¿Cuántas veces se ejecuta el cuerpo del ciclo?

for (let i = 0; i < 5; i++) {
    console.log("Proceso");
}

¿Qué valor imprime contador?

let contador = 0;

for (let i = 1; i <= 10; i++) {
    if (i % 2 === 0) {
        contador++;
    }
}

console.log(contador);

¿Qué se muestra en consola?

for (let i = 1; i <= 7; i += 2) {
    console.log(i);
}

¿Cuál es el valor final de suma?

let numeros = [2, 4, 6];
let suma = 0;

for (let i = 0; i < numeros.length; i++) {
    suma += numeros[i];
}

console.log(suma);

¿Qué valor se imprime al finalizar el ciclo?

let numero = 1;

while (numero < 10) {
    numero = numero * 2;
}

console.log(numero);

¿Cuántas veces se ejecuta el ciclo while?

let intentos = 0;

while (intentos < 3) {
    intentos++;
}

¿Cuál es el valor final de contador?

let contador = 5;

while (contador > 2) {
    contador--;
}

console.log(contador);

¿Qué se muestra en consola?

let x = 3;

while (x < 10) {
    x += 3;
}

console.log(x);

¿Qué se muestra en consola?

let opcion = 2;

switch (opcion) {
    case 1:
        console.log("Crear");
        break;
    case 2:
        console.log("Editar");
        break;
    case 3:
        console.log("Eliminar");
        break;
    default:
        console.log("Opción inválida");
}

¿Qué imprime el siguiente switch?

let dia = 3;

switch (dia) {
    case 1:
        console.log("Lunes");
        break;
    case 3:
        console.log("Miércoles");
        break;
    case 5:
        console.log("Viernes");
        break;
    default:
        console.log("Día inválido");
}

options:
let suma = 0;
for (let i = 1; i <= 5; i++) {
    suma += i;
}

let suma = 0;
for (let i = 1; i <= 5; i++) {
    suma = i;
}

questions.text:
El programador quiere imprimir 'Mayor' cuando edad sea 18 o más. ¿Cuál corrección debe hacer?

let edad = 18;

if (edad > 18) {
    console.log("Mayor");
}

¿Qué problema tiene el siguiente ciclo?

let i = 0;

while (i < 5) {
    console.log(i);
}

¿Qué resultado produce el siguiente algoritmo?

let a = 10;
let b = 10;

if (a > b) {
    console.log("Mayor");
} else if (a < b) {
    console.log("Menor");
} else {
    console.log("Igual");
}
